use reqwest::blocking::Client;
use serde::{Deserialize,Serialize};
use sha2::{Digest,Sha256};
use std::{fs::{self,File},io::{Read,Write},path::{Path,PathBuf},process::{Command,Stdio},time::{Duration,Instant,SystemTime,UNIX_EPOCH}};
use tauri::{AppHandle,Manager};
const REPO:&str="enatneuroeducacao-glitch/MB.Optica";const IMAGE:&str="mb-optica-local:pilot";const DB:&str="mb-gestao-optica-piloto-db-1";const PROJECT:&str="mb-gestao-optica-piloto";
#[derive(Debug,Clone,Serialize,Deserialize)]#[serde(rename_all="camelCase")]pub struct UpdateInfo{pub version:String,pub image_url:String,pub sha256:String,pub notes:Option<String>}
fn docker()->Result<PathBuf,String>{if let Ok(p)=std::env::var("MB_GESTAO_DOCKER_EXE"){let p=PathBuf::from(p);if p.is_file(){return Ok(p)}}if let Ok(p)=std::env::var("PATH"){for d in std::env::split_paths(&p){let x=d.join("docker.exe");if x.is_file(){return Ok(x)}}}let p=PathBuf::from(r"C:\Program Files\Docker\Docker\resources\bin\docker.exe");if p.is_file(){Ok(p)}else{Err("Docker Desktop não foi encontrado.".into())}}
fn run(x:&Path,a:&[&str])->Result<Vec<u8>,String>{let o=Command::new(x).args(a).output().map_err(|e|e.to_string())?;if o.status.success(){Ok(o.stdout)}else{Err(String::from_utf8_lossy(&o.stderr).to_string())}}
fn args(env:&Path,compose:&Path,tail:&[&str])->Vec<String>{let mut a=vec!["compose".into(),"--env-file".into(),env.to_string_lossy().into_owned(),"-p".into(),PROJECT.into(),"-f".into(),compose.to_string_lossy().into_owned()];a.extend(tail.iter().map(|s|s.to_string()));a}
fn version_path(app:&AppHandle)->Result<PathBuf,String>{Ok(app.path().app_data_dir().map_err(|e|e.to_string())?.join("server-version.txt"))}
fn installed(app:&AppHandle)->String{version_path(app).ok().and_then(|p|fs::read_to_string(p).ok()).map(|s|s.trim().to_string()).filter(|s|!s.is_empty()).unwrap_or_else(||"0.1.0".into())}
fn parts(s:&str)->Option<Vec<u64>>{let s=s.trim_start_matches('v');if s.is_empty()||!s.chars().all(|c|c.is_ascii_digit()||c=='.'){return None}s.split('.').map(|x|x.parse().ok()).collect()}
fn newer(a:&str,b:&str)->bool{match(parts(a),parts(b)){(Some(mut x),Some(mut y))=>{x.resize(4,0);y.resize(4,0);x>y},_=>false}}
fn manifest()->Result<UpdateInfo,String>{let c=Client::builder().timeout(Duration::from_secs(90)).user_agent("MB-Gestao-Updater").build().map_err(|e|e.to_string())?;let r:serde_json::Value=c.get(format!("https://api.github.com/repos/{REPO}/releases/latest")).send().map_err(|e|e.to_string())?.error_for_status().map_err(|e|e.to_string())?.json().map_err(|e|e.to_string())?;let u=r["assets"].as_array().and_then(|a|a.iter().find(|x|x["name"]=="mb-gestao-update.json")).and_then(|x|x["browser_download_url"].as_str()).ok_or("Manifesto de atualização não encontrado na publicação.")?;c.get(u).send().map_err(|e|e.to_string())?.error_for_status().map_err(|e|e.to_string())?.json().map_err(|e|e.to_string())}
#[tauri::command]pub fn check_for_update(app:AppHandle)->Result<Option<UpdateInfo>,String>{let m=manifest()?;Ok(if newer(&m.version,&installed(&app)){Some(m)}else{None})}
fn hash(p:&Path)->Result<String,String>{let mut f=File::open(p).map_err(|e|e.to_string())?;let mut h=Sha256::new();let mut b=[0;1024*1024];loop{let n=f.read(&mut b).map_err(|e|e.to_string())?;if n==0{break}h.update(&b[..n]);}Ok(format!("{:x}",h.finalize()))}
fn ready()->bool{let c=match Client::builder().timeout(Duration::from_secs(4)).build(){Ok(c)=>c,Err(_)=>return false};let end=Instant::now()+Duration::from_secs(240);while Instant::now()<end{if c.get("http://127.0.0.1:3000/api/health/ready").send().map(|r|r.status().is_success()).unwrap_or(false){return true}std::thread::sleep(Duration::from_secs(3));}false}
fn restore_db(x:&Path,b:&Path)->Result<(),String>{let sql="DROP SCHEMA public CASCADE; CREATE SCHEMA public; GRANT ALL ON SCHEMA public TO mb_optica; GRANT ALL ON SCHEMA public TO public;";run(x,&["exec",DB,"psql","-U","mb_optica","-d","mb_optica","-c",sql])?;let mut src=File::open(b).map_err(|e|e.to_string())?;let mut child=Command::new(x).args(["exec","-i",DB,"psql","-v","ON_ERROR_STOP=1","-U","mb_optica","-d","mb_optica"]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().map_err(|e|e.to_string())?;let mut stdin=child.stdin.take().ok_or("Entrada de restauração indisponível")?;std::io::copy(&mut src,&mut stdin).map_err(|e|e.to_string())?;drop(stdin);let o=child.wait_with_output().map_err(|e|e.to_string())?;if !o.status.success(){return Err(String::from_utf8_lossy(&o.stderr).to_string())}Ok(())}
fn stamp()->String{SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_secs().to_string()}
#[tauri::command]pub fn apply_update(app:AppHandle)->Result<String,String>{let m=manifest()?;let old=installed(&app);if !newer(&m.version,&old){return Ok("Esta instalação já está atualizada.".into())}if !m.image_url.starts_with("https://")||m.sha256.len()!=64||!m.sha256.chars().all(|c|c.is_ascii_hexdigit()){return Err("Manifesto não passou na validação de segurança.".into())}let data=app.path().app_data_dir().map_err(|e|e.to_string())?;let resources=app.path().resource_dir().map_err(|e|e.to_string())?;let env=data.join(".env");let compose=resources.join("compose.yaml");if !env.is_file()||!compose.is_file(){return Err("Configuração local não encontrada; nenhum dado foi alterado.".into())}let id=stamp();let backups=data.join("updates").join("backups");fs::create_dir_all(&backups).map_err(|e|e.to_string())?;let backup=backups.join(format!("database-before-{id}.sql"));let image=data.join("updates").join(format!("server-{id}.tar"));let x=docker()?;run(&x,&["info"])?;let dump=run(&x,&["exec",DB,"pg_dump","-U","mb_optica","-d","mb_optica","--no-owner","--no-acl"])?;if dump.is_empty(){return Err("Backup vazio; atualização cancelada.".into())}fs::write(&backup,dump).map_err(|e|e.to_string())?;let previous=format!("mb-optica-local:rollback-{id}");run(&x,&["image","tag",IMAGE,&previous])?;let c=Client::builder().timeout(Duration::from_secs(1800)).user_agent("MB-Gestao-Updater").build().map_err(|e|e.to_string())?;let mut r=c.get(&m.image_url).send().map_err(|e|e.to_string())?.error_for_status().map_err(|e|e.to_string())?;let mut f=File::create(&image).map_err(|e|e.to_string())?;r.copy_to(&mut f).map_err(|e|e.to_string())?;f.flush().map_err(|e|e.to_string())?;drop(f);if hash(&image)?.to_lowercase()!=m.sha256.to_lowercase(){let _=fs::remove_file(&image);return Err("SHA-256 divergente. Versão atual preservada.".into())}let p=image.to_string_lossy().to_string();run(&x,&["load","-i",&p])?;let ca=args(&env,&compose,&["up","-d","--no-deps","--force-recreate","app"]);let cr=ca.iter().map(String::as_str).collect::<Vec<_>>();if let Err(e)=run(&x,&cr){let _=run(&x,&["image","tag",&previous,IMAGE]);let _=run(&x,&cr);return Err(format!("Falha ao iniciar atualização; rollback da imagem acionado. Backup: {}. {e}",backup.display()))}if !ready(){let sa=args(&env,&compose,&["stop","app"]);let sr=sa.iter().map(String::as_str).collect::<Vec<_>>();let _=run(&x,&sr);let db=restore_db(&x,&backup);let _=run(&x,&["image","tag",&previous,IMAGE]);let _=run(&x,&cr);let ok=ready();return Err(format!("Validação de saúde falhou. Rollback da imagem: {}. Restauração do banco: {}. Serviço anterior saudável: {}. Backup: {}",previous,if db.is_ok(){"concluída"}else{"FALHOU"},if ok{"sim"}else{"não confirmado"},backup.display()))}fs::write(version_path(&app)?,m.version.clone()).map_err(|e|e.to_string())?;Ok(format!("Atualizado para {}. Backup: {}. Imagem anterior preservada: {}.",m.version,backup.display(),previous))}
